#include "AdminAccessController.h"
namespace vox {AdminAccessController::AdminAccessController()=default;bool AdminAccessController::begin(const UserAccount&u,int minutes){authenticated=u.id.isNotEmpty()&&u.status==UserStatus::Active&&u.role!=Role::User;sessionUser=u;expires=juce::Time::getCurrentTime()+juce::RelativeTime::minutes(minutes);return active();}bool AdminAccessController::active()const{return authenticated&&juce::Time::getCurrentTime()<expires;}bool AdminAccessController::can(Permission p)const{return active()&&permissions.allowed(sessionUser.role,p);}void AdminAccessController::lock(){authenticated=false;}}
